"""Runtime support for vecDSL programs generated for Pinecone with the pinecone SDK. Generated by vecDSL 7. Do not edit."""

from __future__ import annotations

import json
import math
import os
import random
import re
import time
import urllib.error
import urllib.parse
import urllib.request
from importlib.metadata import PackageNotFoundError, version
from typing import Any, Iterator, NoReturn, Sequence

SDK_PACKAGE = "{{sdk.python.package}}"
SDK_MIN = "{{sdk.python.min}}"
SDK_MAX = "{{sdk.python.max}}"
API_VERSION = "{{api.version}}"
DEFAULT_NAMESPACE = "{{namespace}}"
DEFAULT_CLOUD = "{{deployment.cloud}}"
DEFAULT_REGION = "{{deployment.region}}"

_PAGE = 1000
_LIST_PAGE = 100
_BATCH = 100
_SETTLE = 50
_DIGITS = 6
_MAX_ID = 512
_RETRIES = 3
_RETRIED = {429, 500, 502, 503, 504}
_EMBEDDED_BATCH = 96
_OPERATORS = {"and", "or", "not"}


class UnsupportedFeature(NotImplementedError):
    pass


def _version_tuple(text: str) -> tuple[int, ...]:
    parts = []
    for token in re.split(r"[.+\-]", text.lstrip("v")):
        if not token.isdigit():
            break
        parts.append(int(token))
    return tuple(parts)


def requirement() -> str:
    return f"{SDK_PACKAGE}>={SDK_MIN},<{SDK_MAX}"


def check_sdk() -> str:
    try:
        installed = version(SDK_PACKAGE)
    except PackageNotFoundError as error:
        raise ImportError(f"{SDK_PACKAGE} is not installed; install '{requirement()}'") from error
    if not _version_tuple(SDK_MIN) <= _version_tuple(installed) < _version_tuple(SDK_MAX):
        raise ImportError(f"{SDK_PACKAGE} {installed} is not supported; install '{requirement()}'")
    return installed


check_sdk()

from pinecone import NotFoundError, Pinecone  # noqa: E402


def unsupported(vendor: str, feature: str) -> NoReturn:
    raise UnsupportedFeature(f"{feature} is not supported for target {vendor}")


def env(name: str) -> str:
    value = os.environ.get(name)
    if value is None:
        raise KeyError(f"environment variable {name} is not set")
    return value


def _seconds(name: str, default: float) -> float:
    return float(os.environ.get(name, default))


class PineconeError(RuntimeError):
    """A Pinecone REST response with a status other than 2xx."""

    def __init__(self, status: int, message: str) -> None:
        super().__init__(message)
        self.status = status


class Client:
    """The Pinecone client, the data-plane handles of the indexes a program uses, and what REST calls need."""

    def __init__(self, pinecone: Pinecone, index_host: str | None, uri: str, api_key: str, timeout: float | None) -> None:
        self.pinecone = pinecone
        self.index_host = index_host
        self.uri = uri.rstrip("/")
        self.api_key = api_key
        self.timeout = timeout or 30.0
        self._indexes: dict[str, Any] = {}
        self._hosts: dict[str, str] = {}
        self.schemas: dict[str, set[str]] = {}
        self.committed: int | None = None
        self.reconciled: int | None = None

    def index(self, name: str) -> Any:
        if name not in self._indexes:
            self._indexes[name] = self.pinecone.index(host=self.index_host) if self.index_host \
                else self.pinecone.index(name=name)
        return self._indexes[name]

    def forget(self, name: str) -> None:
        self._hosts.pop(name, None)
        self.schemas.pop(name, None)
        handle = self._indexes.pop(name, None)
        if handle is not None:
            handle.close()

    def close(self) -> None:
        for name in list(self._indexes):
            self.forget(name)
        self.pinecone.close()


def connect(uri: str, api_key: str, index_host: str | None = None, timeout: float | None = None) -> Client:
    options: dict[str, Any] = {"api_key": api_key, "host": uri}
    if timeout is not None:
        options["timeout"] = timeout
    return Client(Pinecone(**options), index_host or None, uri, api_key, timeout)


def _send(client: Client, method: str, url: str, body: Any = None) -> Any:
    """One REST request of API {{api.version}}; 429 and 5xx are retried three times with backoff from 0.5 s, and so is a
    dropped connection when the request can be repeated (reads, deletes and document writes)."""
    data = None if body is None else json.dumps(body).encode("utf-8")
    headers = {"Api-Key": client.api_key, "X-Pinecone-Api-Version": API_VERSION, "Accept": "application/json"}
    if data is not None:
        headers["Content-Type"] = "application/json"
    repeatable = method != "POST" or "/documents/" in url
    for attempt in range(_RETRIES + 1):
        request = urllib.request.Request(url, data=data, method=method, headers=headers)
        try:
            with urllib.request.urlopen(request, timeout=client.timeout) as response:
                text = response.read().decode("utf-8")
                client.committed = _header_position(response.headers, "x-pinecone-request-lsn", "x-pinecone-lsn-committed")
                client.reconciled = _header_position(response.headers, "x-pinecone-max-indexed-lsn", "x-pinecone-lsn-reconciled")
            return json.loads(text) if text.strip() else None
        except urllib.error.HTTPError as error:
            text = error.read().decode("utf-8", "replace")
            if error.code in _RETRIED and attempt < _RETRIES:
                time.sleep(0.5 * 2 ** attempt)
                continue
            raise PineconeError(error.code, f"{method} {url} returned {error.code}: {text}") from None
        except (urllib.error.URLError, ConnectionError, TimeoutError):
            if repeatable and attempt < _RETRIES:
                time.sleep(0.5 * 2 ** attempt)
                continue
            raise
    raise AssertionError("unreachable")


def _header_position(headers: Any, *names: str) -> int | None:
    for name in names:
        value = headers.get(name)
        if value is not None and value.strip().isdigit():
            return int(value.strip())
    return None


def _segment(name: str) -> str:
    return urllib.parse.quote(name, safe="")


def _control(client: Client, method: str, path: str, body: Any = None) -> Any:
    return _send(client, method, client.uri + path, body)


def _host(client: Client, name: str) -> str:
    found = client.index_host or client._hosts.get(name)
    if found is None:
        found = _control(client, "GET", "/indexes/" + _segment(name))["host"]
        client._hosts[name] = found
    return found.rstrip("/") if "://" in found else "https://" + found


def _data(client: Client, name: str, method: str, path: str, body: Any = None) -> Any:
    return _send(client, method, _host(client, name) + path, body)


def _query(**parameters: Any) -> str:
    present = {key: value for key, value in parameters.items() if value is not None}
    return "?" + urllib.parse.urlencode(present) if present else ""


def _paged(fetch: Any, items: str, token_name: str = "paginationToken") -> list[Any]:
    """Every item of a paginated listing; a repeated token ends the listing."""
    found: list[Any] = []
    token: str | None = None
    seen: set[str] = set()
    while True:
        page = fetch(token) or {}
        found.extend(page.get(items) or [])
        following = (page.get("pagination") or {}).get("next")
        if not following or following in seen:
            return found
        seen.add(following)
        token = following


def _poll(done: Any, what: str, limit: float) -> None:
    """Polls every second until done() holds, for at most limit seconds; a limit of 0 skips the wait (API mock)."""
    if limit <= 0:
        return
    deadline = time.monotonic() + limit
    while not done():
        if time.monotonic() > deadline:
            raise TimeoutError(f"{what} after {limit:g} s")
        time.sleep(1.0)


def document_id(key: Any) -> str:
    """Pinecone document id of a primary key: the decimal text of an integer, or the text itself."""
    if isinstance(key, bool) or not isinstance(key, (int, float, str)):
        raise TypeError(f"cannot use {key!r} as a Pinecone primary key")
    if isinstance(key, float):
        if not key.is_integer():
            raise TypeError(f"cannot use {key!r} as a Pinecone primary key")
        key = int(key)
    text = str(key)
    if not text or len(text) > _MAX_ID or any(not 0 < ord(c) < 128 for c in text):
        raise ValueError(f"Pinecone document ids are 1 to {_MAX_ID} ASCII characters: {text!r}")
    return text


def _key(collection: dict[str, Any], doc_id: str) -> Any:
    return int(doc_id) if collection["key_type"] == "int" else doc_id


def _order(collection: dict[str, Any]) -> Any:
    return (lambda doc_id: int(doc_id)) if collection["key_type"] == "int" else (lambda doc_id: doc_id)


def _value(value: Any) -> Any:
    """Result values in one form for every host language: floats rounded, integral floats as integers."""
    if isinstance(value, float):
        rounded = round(value, _DIGITS)
        return int(rounded) if rounded.is_integer() else rounded
    if isinstance(value, (list, tuple)):
        return [_value(item) for item in value]
    if isinstance(value, dict):
        return {key: _value(item) for key, item in value.items()}
    return value


def _documents(client: Client, collection: dict[str, Any]) -> Any:
    return client.index(collection["name"]).documents


def _chunks(items: Sequence[Any], size: int) -> Iterator[Sequence[Any]]:
    for start in range(0, len(items), size):
        yield items[start:start + size]


def _batch(collection: dict[str, Any], size: int) -> int:
    """Documents per upsert or update: at most 96 on an index that embeds a field."""
    return min(int(size), int(collection.get("max_batch", size)))


# ---------------------------------------------------------------- indexes

def _index_timeout() -> int:
    seconds = int(_seconds("VECDSL_PINECONE_INDEX_TIMEOUT", 300))
    return -1 if seconds == 0 else seconds


def has_collection(client: Client, name: str) -> bool:
    return client.pinecone.indexes.exists(name)


def drop_collection(client: Client, name: str) -> None:
    client.forget(name)
    try:
        client.pinecone.indexes.delete(name, timeout=_index_timeout())
    except NotFoundError:
        pass


def create_collection(client: Client, name: str, fields: dict[str, Any], deployment: dict[str, Any] | None = None,
                      deletion_protection: str | None = None, tags: dict[str, str] | None = None) -> None:
    target = {"deployment_type": "managed",
              "cloud": os.environ.get("VECDSL_PINECONE_CLOUD", DEFAULT_CLOUD),
              "region": os.environ.get("VECDSL_PINECONE_REGION", DEFAULT_REGION),
              **(deployment or {})}
    options: dict[str, Any] = {"name": name, "schema": {"fields": fields}, "deployment": target,
                               "timeout": _index_timeout()}
    if deletion_protection is not None:
        options["deletion_protection"] = deletion_protection
    if tags:
        options["tags"] = tags
    client.pinecone.indexes.create(**options)


def _describe(client: Client, name: str) -> dict[str, Any]:
    return _control(client, "GET", "/indexes/" + _segment(name))


def require_collection(client: Client, name: str) -> None:
    if not has_collection(client, name):
        raise KeyError(f"index {name} does not exist")


def _ready(client: Client, name: str) -> bool:
    return bool((_describe(client, name).get("status") or {}).get("ready"))


def configure_collection(client: Client, name: str, tags: dict[str, str] | None = None, replace_tags: bool = False,
                         deletion_protection: str | None = None) -> None:
    """configure_index: tags (replace_tags clears the tags not given, which Pinecone removes when set to "") and
    deletion protection; then waits until the index is ready again."""
    body: dict[str, Any] = {}
    if tags is not None:
        current = (_describe(client, name).get("tags") or {}) if replace_tags else {}
        body["tags"] = {**{key: "" for key in current if key not in tags}, **tags}
    if deletion_protection is not None:
        body["deletion_protection"] = deletion_protection
    _control(client, "PATCH", "/indexes/" + _segment(name), body)
    _poll(lambda: _ready(client, name), f"index {name} is not ready", _index_timeout_seconds())


def _index_timeout_seconds() -> float:
    return _seconds("VECDSL_PINECONE_INDEX_TIMEOUT", 300)


def has_namespace(client: Client, name: str, namespace: str) -> bool:
    try:
        _data(client, name, "GET", "/namespaces/" + _segment(namespace))
        return True
    except PineconeError as error:
        if error.status == 404:
            return False
        raise


def create_namespace(client: Client, name: str, namespace: str) -> None:
    _data(client, name, "POST", "/namespaces", {"name": namespace})


def drop_namespace(client: Client, name: str, namespace: str) -> None:
    """Deletes a namespace with its documents and waits until it is gone."""
    _data(client, name, "DELETE", "/namespaces/" + _segment(namespace))
    _poll(lambda: not has_namespace(client, name, namespace), f"namespace {namespace} of {name} still exists",
          _index_timeout_seconds())


def require_model(client: Client, model: str) -> None:
    """A hosted embedding or reranking model (GET /models/{model}); unknown models fail with 404."""
    _control(client, "GET", "/models/" + _segment(model))


def _schedules(client: Client, name: str) -> list[dict[str, Any]]:
    return _paged(lambda token: _control(client, "GET", f"/indexes/{_segment(name)}/backup-schedules"
                                         + _query(paginationToken=token)), "data")


def has_backup_schedule(client: Client, name: str, schedule: str) -> bool:
    return any(item.get("name") == schedule for item in _schedules(client, name))


def create_backup_schedule(client: Client, name: str, schedule: str, frequency: str, expire_after_days: int) -> None:
    _control(client, "POST", f"/indexes/{_segment(name)}/backup-schedules",
             {"name": schedule, "schedule": {"type": "time-based", "frequency": frequency},
              "retention": {"expire_after_days": int(expire_after_days)}})


def drop_backup_schedule(client: Client, name: str, schedule: str) -> None:
    found = [item for item in _schedules(client, name) if item.get("name") == schedule]
    if not found:
        raise KeyError(f"backup schedule {schedule} of {name} does not exist")
    for item in found:
        _control(client, "DELETE", "/backup-schedules/" + _segment(item["schedule_id"]))


# ---------------------------------------------------------------- writes

def _check(collection: dict[str, Any], record: dict[str, Any]) -> None:
    for field, limit in collection.get("limits", {}).items():
        value = record.get(field)
        if value is None:
            continue
        if "dim" in limit and len(value) != limit["dim"]:
            raise ValueError(f"{field} has {len(value)} dimensions; {collection['name']} declares {limit['dim']}")
        if "max_items" in limit and len(value) > limit["max_items"]:
            raise ValueError(f"{field} has {len(value)} items; at most {limit['max_items']} are allowed")
        if "max_length" in limit:
            for text in value if isinstance(value, list) else [value]:
                if isinstance(text, str) and len(text) > limit["max_length"]:
                    raise ValueError(f"{field} is longer than {limit['max_length']} characters")


def _fields(collection: dict[str, Any], record: dict[str, Any]) -> dict[str, Any]:
    """Document fields of a record; Pinecone stores no nulls, so absent and null are the same."""
    _check(collection, record)
    return {name: value for name, value in record.items() if value is not None}


def _document(collection: dict[str, Any], row: dict[str, Any]) -> dict[str, Any]:
    record = {**collection.get("defaults", {}), **row}
    key = record.get(collection["key"])
    if key is None:
        raise ValueError(f"record without primary key {collection['key']}: {row}")
    return {"_id": document_id(key), **_fields(collection, record)}


def _lsn(response: Any) -> int | None:
    info = response.response_info
    return None if info is None else info.lsn_committed


def _latest(positions: Sequence[int | None]) -> int | None:
    known = [position for position in positions if position is not None]
    return max(known) if known else None


def _await(client: Client, collection: dict[str, Any], target: int | None, written: Sequence[dict[str, Any]] = (),
           deleted: Sequence[str] = ()) -> None:
    """Waits until searches see a write (the index's reconciled log position reaches the write's) and then
    until filtered fetches see it too."""
    deadline = time.monotonic() + _seconds("VECDSL_PINECONE_WAIT_SECONDS", 60)
    if target is not None:
        _await_position(client, collection, target, deadline)
    _settle(client, collection, written, deleted, deadline)


def _await_position(client: Client, collection: dict[str, Any], target: int, deadline: float) -> None:
    probe = collection["probe"]
    clause: dict[str, Any] = {"type": probe["type"], "field": probe["field"]}
    if probe["type"] == "dense_vector":
        clause["values"] = [1.0] + [0.0] * (int(probe["dim"]) - 1)
    else:
        clause["query"] = "vecdsl"
    while True:
        response = _documents(client, collection).search(namespace=collection["namespace"], top_k=1, score_by=[clause])
        reached = None if response.response_info is None else response.response_info.lsn_reconciled
        if reached is not None and reached >= target:
            return
        if time.monotonic() > deadline:
            raise TimeoutError(f"{collection['name']} did not reach log position {target}")
        time.sleep(0.5)


def _schema_fields(client: Client, name: str) -> set[str]:
    """Names of the fields an index declares (vectors and full-text text); every other field is metadata."""
    if name not in client.schemas:
        client.schemas[name] = set((_describe(client, name).get("schema") or {}).get("fields") or {})
    return client.schemas[name]


def _condition(collection: dict[str, Any], declared: set[str], document: dict[str, Any]) -> dict[str, Any]:
    """A filter that matches a written document only once filtering sees its metadata as written."""
    parts: list[dict[str, Any]] = [{collection["key"]: {"$eq": _key(collection, document["_id"])}}]
    for name, value in document.items():
        if name.startswith("_") or name == collection["key"] or name in declared:
            continue
        if isinstance(value, (bool, int, float, str)):
            parts.append({name: {"$eq": value}})
    parts.extend({name: {"$exists": False}} for name in document.get("_remove_fields", ()) if name not in declared)
    return parts[0] if len(parts) == 1 else {"$and": parts}


def _settle(client: Client, collection: dict[str, Any], written: Sequence[dict[str, Any]], deleted: Sequence[str],
            deadline: float) -> None:
    """Filtered fetches see writes seconds after searches and report no log position, so the written documents are
    fetched by filter until all match as written and none of the deleted ones is found."""
    if not written and not deleted:
        return
    declared = _schema_fields(client, collection["name"])
    latest = {document["_id"]: document for document in written}
    checks: list[tuple[dict[str, Any], int]] = []
    for chunk in _chunks(list(latest.values()), _SETTLE):
        conditions = [_condition(collection, declared, document) for document in chunk]
        checks.append((conditions[0] if len(conditions) == 1 else {"$or": conditions}, len(chunk)))
    for chunk in _chunks(list(dict.fromkeys(deleted)), _SETTLE):
        checks.append(({collection["key"]: {"$in": [_key(collection, doc_id) for doc_id in chunk]}}, 0))
    while True:
        checks = [(where, count) for where, count in checks if len(_matching(client, collection, where)) != count]
        if not checks:
            return
        if time.monotonic() > deadline:
            raise TimeoutError(f"filtered reads of {collection['name']} do not see the last write yet")
        time.sleep(0.5)


def _existing(client: Client, collection: dict[str, Any], doc_ids: Sequence[str]) -> set[str]:
    found: set[str] = set()
    for chunk in _chunks(list(doc_ids), _PAGE):
        response = _documents(client, collection).fetch(namespace=collection["namespace"], ids=list(chunk),
                                                         include_fields=[collection["key"]])
        found.update(response.documents)
    return found


def _matching(client: Client, collection: dict[str, Any], where: dict[str, Any]) -> list[str]:
    """Ids of every document that matches a filter, through paginated fetches."""
    found: dict[str, None] = {}
    token: str | None = None
    while True:
        options: dict[str, Any] = {"namespace": collection["namespace"], "filter": where,
                                   "include_fields": [collection["key"]], "limit": _PAGE}
        if token is not None:
            options["pagination_token"] = token
        response = _documents(client, collection).fetch(**options)
        found.update(dict.fromkeys(response.documents))
        following = None if response.pagination is None else response.pagination.next
        if not following or following == token:
            return list(found)
        token = following


def _all_ids(client: Client, collection: dict[str, Any]) -> list[str]:
    found: list[str] = []
    seen: set[str | None] = set()
    pages = _documents(client, collection).list(namespace=collection["namespace"], limit=_LIST_PAGE).pages()
    for page in pages:
        found.extend(item.id for item in page.items)
        if page.pagination_token is None or page.pagination_token in seen:
            break
        seen.add(page.pagination_token)
    return found


def _targets(client: Client, collection: dict[str, Any], ids: Sequence[Any] | None,
             filter: dict[str, Any] | None) -> list[str]:
    if ids:
        wanted = [document_id(key) for key in ids]
        existing = _existing(client, collection, wanted)
        targets = [doc_id for doc_id in dict.fromkeys(wanted) if doc_id in existing]
        if filter is not None:
            matching = set(_matching(client, collection, filter))
            targets = [doc_id for doc_id in targets if doc_id in matching]
        return targets
    if filter is not None:
        return _matching(client, collection, filter)
    raise ValueError("the statement selects no records")


def _upsert(client: Client, collection: dict[str, Any], documents: Sequence[dict[str, Any]], batch_size: int) -> int | None:
    positions = []
    for chunk in _chunks(list(documents), _batch(collection, batch_size)):
        response = _documents(client, collection).upsert(namespace=collection["namespace"], documents=list(chunk))
        positions.append(_lsn(response))
    return _latest(positions)


def insert_rows(client: Client, collection: dict[str, Any], rows: Sequence[dict[str, Any]], on_conflict: str = "error",
                batch_size: int = _BATCH, wait: bool = False) -> dict[str, int]:
    documents = [_document(collection, row) for row in rows]
    existing = _existing(client, collection, [document["_id"] for document in documents])
    if existing and on_conflict == "error":
        raise ValueError(f"{len(existing)} records already exist in {collection['name']}")
    fresh = [document for document in documents if document["_id"] not in existing]
    position = _upsert(client, collection, fresh, batch_size)
    if wait:
        _await(client, collection, position, fresh)
    return {"insert_count": len(fresh), "skipped": len(documents) - len(fresh)}


def upsert_rows(client: Client, collection: dict[str, Any], rows: Sequence[dict[str, Any]], batch_size: int = _BATCH,
                wait: bool = False) -> dict[str, int]:
    documents = [_document(collection, row) for row in rows]
    position = _upsert(client, collection, documents, batch_size)
    if wait:
        _await(client, collection, position, documents)
    return {"upsert_count": len(documents)}


def update_rows(client: Client, collection: dict[str, Any], ids: Sequence[Any] | None = None,
                filter: dict[str, Any] | None = None, values: dict[str, Any] | None = None,
                rows: Sequence[dict[str, Any]] | None = None, remove: Sequence[str] | None = None,
                mode: str = "merge", append: Sequence[str] = (), remove_items: Sequence[str] = (),
                wait: bool = False) -> dict[str, int]:
    replacements = {document_id(row[collection["key"]]): row for row in rows or []}
    if ids or filter is not None:
        targets = _targets(client, collection, ids, filter)
    elif replacements:
        existing = _existing(client, collection, list(replacements))
        targets = [doc_id for doc_id in replacements if doc_id in existing]
    else:
        raise ValueError("update requires ids, a filter or records")
    arrays = [*append, *remove_items]
    stored = _fetch(client, collection, targets, arrays) if arrays else {}
    patches = []
    for doc_id in targets:
        record = {**replacements.get(doc_id, {}), **(values or {})}
        dropped = list(remove or [])
        for name in arrays:
            current = list(stored.get(doc_id, {}).get(name) or [])
            given = list(record.get(name) or [])
            items = current + given if name in append else [item for item in current if item not in given]
            if items:
                record[name] = items
            else:
                record.pop(name, None)
                dropped.append(name)
        key = record.get(collection["key"])
        if key is not None and document_id(key) != doc_id:
            raise ValueError(f"update cannot change the primary key {collection['key']}")
        record[collection["key"]] = _key(collection, doc_id)
        if mode == "replace":
            patches.append(_document(collection, record))
        else:
            patch = {"_id": doc_id, **_fields(collection, record)}
            if dropped:
                patch["_remove_fields"] = list(dict.fromkeys(dropped))
            patches.append(patch)
    positions = []
    for chunk in _chunks(patches, _batch(collection, _PAGE)):
        if mode == "replace":
            response = _documents(client, collection).upsert(namespace=collection["namespace"], documents=list(chunk))
        else:
            response = _documents(client, collection).update(namespace=collection["namespace"], documents=list(chunk))
        positions.append(_lsn(response))
    if wait:
        _await(client, collection, _latest(positions), patches)
    return {"update_count": len(targets)}


def delete_rows(client: Client, collection: dict[str, Any], ids: Sequence[Any] | None = None,
                filter: dict[str, Any] | None = None, delete_all: bool = False, limit: int | None = None,
                wait: bool = False) -> dict[str, int]:
    """Deletes by id after resolving the targets, so the count is exact; limit takes the first targets in key order."""
    documents = _documents(client, collection)
    if limit is not None:
        targets = sorted(_all_ids(client, collection) if delete_all and filter is None and not ids
                         else _targets(client, collection, ids, filter), key=_order(collection))[:int(limit)]
        positions = [_lsn(documents.delete(namespace=collection["namespace"], ids=list(chunk)))
                     for chunk in _chunks(targets, _PAGE)]
    elif delete_all:
        targets = _all_ids(client, collection)
        positions = [_lsn(documents.delete(namespace=collection["namespace"], delete_all=True))] if targets else []
    else:
        targets = _targets(client, collection, ids, filter)
        positions = [_lsn(documents.delete(namespace=collection["namespace"], ids=list(chunk)))
                     for chunk in _chunks(targets, _PAGE)]
    if wait:
        _await(client, collection, _latest(positions), deleted=targets)
    return {"delete_count": len(targets)}


def rename_field(client: Client, collection: dict[str, Any], field: str, new_name: str, wait: bool = False) -> dict[str, int]:
    """Moves a metadata value to a new key in every document that has it: Pinecone renames no metadata keys."""
    targets = _matching(client, collection, {field: {"$exists": True}})
    stored = _fetch(client, collection, targets, [field])
    patches = [{"_id": doc_id, new_name: stored[doc_id].get(field), "_remove_fields": [field]}
               for doc_id in targets if doc_id in stored and stored[doc_id].get(field) is not None]
    positions = [_lsn(_documents(client, collection).update(namespace=collection["namespace"], documents=list(chunk)))
                 for chunk in _chunks(patches, _batch(collection, _PAGE))]
    if wait:
        _await(client, collection, _latest(positions), patches)
    return {"update_count": len(patches)}


def read_records(client: Client, location: str) -> list[dict[str, Any]]:
    """Records of a local JSON array or JSON Lines file (file:// URI or path)."""
    path = location[len("file://"):] if location.startswith("file://") else location
    with open(path, encoding="utf-8") as handle:
        text = handle.read()
    stripped = text.lstrip()
    if stripped.startswith("["):
        return list(json.loads(stripped))
    return [json.loads(line) for line in text.splitlines() if line.strip()]


def import_file(client: Client, collection: dict[str, Any], location: str, on_conflict: str | None = None,
                batch_size: int = _BATCH, wait: bool = False) -> dict[str, int]:
    """A local file written as an insert (on-conflict error, ignore) or an upsert (update, replace)."""
    rows = read_records(client, location)
    if on_conflict in ("update", "replace"):
        return upsert_rows(client, collection, rows, batch_size, wait)
    return insert_rows(client, collection, rows, on_conflict or "error", batch_size, wait)


def start_import(client: Client, collection: dict[str, Any], uri: str, background: bool = False) -> dict[str, Any]:
    """Bulk import of JSON Lines documents from object storage (paid plans); unless in the background, waits until it ends."""
    started = _data(client, collection["name"], "POST", "/bulk/imports", {"uri": uri, "errorMode": {"onError": "abort"}})
    job = started["id"]

    def status() -> dict[str, Any]:
        return _data(client, collection["name"], "GET", "/bulk/imports/" + _segment(job))

    if not background:
        _poll(lambda: status().get("status") in ("Completed", "Failed", "Cancelled"), f"import {job} has not finished",
              _seconds("VECDSL_PINECONE_IMPORT_TIMEOUT", 3600))
    final = status()
    if final.get("status") in ("Failed", "Cancelled"):
        raise RuntimeError(f"import {job} ended {final.get('status')}: {final.get('error')}")
    return {"import": job, "status": final.get("status"), "records": final.get("recordsImported")}


# ---------------------------------------------------------------- reads

def _included(collection: dict[str, Any], output: Sequence[str], vectors: Sequence[str] | None) -> list[str]:
    return list(dict.fromkeys([collection["key"], *output, *(vectors or ())]))


def _row(collection: dict[str, Any], doc_id: str, document: Any, output: Sequence[str],
         vectors: Sequence[str] | None) -> dict[str, Any]:
    row = {collection["key"]: _key(collection, doc_id)}
    for name in [*output, *(vectors or ())]:
        row[name] = _value(document.get(name))
    return row


def _fetch(client: Client, collection: dict[str, Any], doc_ids: Sequence[str], fields: Sequence[str]) -> dict[str, Any]:
    found: dict[str, Any] = {}
    for chunk in _chunks(list(doc_ids), _PAGE):
        response = _documents(client, collection).fetch(namespace=collection["namespace"], ids=list(chunk),
                                                         include_fields=list(fields))
        found.update(response.documents)
    return found


def get_rows(client: Client, collection: dict[str, Any], ids: Sequence[Any], output: Sequence[str],
             vectors: Sequence[str] | None = None) -> list[dict[str, Any]]:
    doc_ids = list(dict.fromkeys(document_id(key) for key in ids))
    found = _fetch(client, collection, doc_ids, _included(collection, output, vectors))
    return [_row(collection, doc_id, found[doc_id], output, vectors) for doc_id in doc_ids if doc_id in found]


def count(client: Client, collection: dict[str, Any], filter: dict[str, Any] | None = None) -> int:
    if filter is None:
        return len(_all_ids(client, collection))
    return len(_matching(client, collection, filter))


def _sorted(doc_ids: list[str], stored: dict[str, Any], order: Sequence[dict[str, Any]]) -> list[str]:
    """Stable sorts from the last sort key to the first; documents without a value come last for every key."""
    for clause in reversed(order):
        name = clause["key"]
        present = [doc_id for doc_id in doc_ids if stored.get(doc_id, {}).get(name) is not None]
        absent = [doc_id for doc_id in doc_ids if stored.get(doc_id, {}).get(name) is None]
        present.sort(key=lambda doc_id: stored[doc_id].get(name), reverse=clause.get("direction") == "desc")
        doc_ids = present + absent
    return doc_ids


def scroll(client: Client, collection: dict[str, Any], output: Sequence[str], filter: dict[str, Any] | None = None,
           limit: int | None = None, offset: int | None = None, vectors: Sequence[str] | None = None,
           order: Sequence[dict[str, Any]] = ()) -> list[dict[str, Any]]:
    """Records in primary-key order, or by the sort keys and then the key; Pinecone lists ids only, so the runtime sorts."""
    doc_ids = _all_ids(client, collection) if filter is None else _matching(client, collection, filter)
    doc_ids = sorted(doc_ids, key=_order(collection))
    if order:
        doc_ids = _sorted(doc_ids, _fetch(client, collection, doc_ids, [clause["key"] for clause in order]), order)
    doc_ids = doc_ids[offset or 0:]
    if limit is not None:
        doc_ids = doc_ids[:limit]
    found = _fetch(client, collection, doc_ids, _included(collection, output, vectors))
    return [_row(collection, doc_id, found[doc_id], output, vectors) for doc_id in doc_ids if doc_id in found]


def _vector(value: Any) -> Any:
    """A stored or literal vector as Pinecone takes it: dense values, or the indices and values of a sparse vector."""
    if isinstance(value, dict):
        return {"indices": [int(i) for i in value["indices"]], "values": [float(x) for x in value["values"]]}
    return [float(x) for x in value]


def _vector_clause(field: str, vector: Any, embed: str | None = None) -> dict[str, Any]:
    """The scoring clause of a vector search: dense_vector, sparse_vector, or embed and sparse_embed with the
    query text of a field Pinecone embeds."""
    if embed is not None:
        return {"type": embed, "field": field, "query": vector}
    if isinstance(vector, dict):
        return {"type": "sparse_vector", "field": field, "sparse_values": _vector(vector)}
    return {"type": "dense_vector", "field": field, "values": _vector(vector)}


def _similarity(metric: str, score: float) -> float:
    """Canonical similarity of a Pinecone score; euclidean scores are squared distances."""
    return -math.sqrt(max(score, 0.0)) if metric == "euclidean" else score


def _search(client: Client, collection: dict[str, Any], clause: dict[str, Any], top_k: int,
            fields: Sequence[str], filter: dict[str, Any] | None) -> list[Any]:
    options: dict[str, Any] = {"namespace": collection["namespace"], "top_k": top_k, "score_by": [clause],
                               "include_fields": list(fields)}
    if filter is not None:
        options["filter"] = filter
    return list(_documents(client, collection).search(**options).matches)


def _hit(collection: dict[str, Any], match: Any, score: float, output: Sequence[str],
         vectors: Sequence[str] | None) -> dict[str, Any]:
    row = _row(collection, match.id, match, output, vectors)
    return {"id": row.pop(collection["key"]), "score": _value(float(score)), **row}


def _within(score: float, score_min: float | None, score_max: float | None) -> bool:
    return (score_min is None or score >= score_min) and (score_max is None or score <= score_max)


def _page(hits: list[Any], limit: int, offset: int | None) -> list[Any]:
    return hits[offset or 0:(offset or 0) + limit]


def _ranked(fields: list[str], rerank: dict[str, Any] | None) -> list[str]:
    """The fields a search returns, with the rank field of a rerank clause."""
    return fields if rerank is None else list(dict.fromkeys([*fields, rerank["field"]]))


def _rerank(client: Client, rerank: dict[str, Any] | None, scored: list[tuple[Any, dict[str, Any]]]) -> list[dict[str, Any]]:
    """Hits in the order of Pinecone Inference rerank: the rank field of each hit scored against the query text;
    a hit's score becomes the reranker's relevance."""
    if rerank is None or not scored:
        return [hit for _, hit in scored]
    field = rerank["field"]
    body: dict[str, Any] = {"model": rerank["model"], "query": rerank["query"], "rank_fields": [field], "return_documents": False,
                            "documents": [{"id": match.id, field: str(match.get(field) or "")} for match, _ in scored]}
    if "top_n" in rerank:
        body["top_n"] = min(int(rerank["top_n"]), len(scored))
    if "parameters" in rerank:
        body["parameters"] = rerank["parameters"]
    ranking = _control(client, "POST", "/rerank", body)["data"]
    return [{**scored[int(item["index"])][1], "score": _value(float(item["score"]))} for item in ranking]


def vector_search(client: Client, collection: dict[str, Any], field: str, vector: Any, limit: int, metric: str,
                  output: Sequence[str], filter: dict[str, Any] | None = None, offset: int | None = None,
                  score_min: float | None = None, score_max: float | None = None, native: bool = False,
                  vectors: Sequence[str] | None = None, embed: str | None = None,
                  rerank: dict[str, Any] | None = None) -> list[dict[str, Any]]:
    clause = _vector_clause(field, vector, embed)
    matches = _search(client, collection, clause, limit + (offset or 0), _ranked(_included(collection, output, vectors), rerank),
                      filter)
    scored = []
    for match in matches:
        score = float(match.score) if native else _similarity(metric, float(match.score))
        if _within(score, score_min, score_max):
            scored.append((match, _hit(collection, match, score, output, vectors)))
    return _page(_rerank(client, rerank, scored), limit, offset)


def _terms(text: str) -> list[str]:
    """The terms of a query text, lowercased: runs of letters and decimal digits; every other character separates terms,
    since Pinecone's query_string syntax documents no escape character."""
    terms: list[str] = []
    current: list[str] = []
    for char in text.lower():
        if char.isalpha() or char.isdecimal():
            current.append(char)
        elif current:
            terms.append("".join(current))
            current = []
    if current:
        terms.append("".join(current))
    return terms


def query_string_text(query: str, fields: Sequence[str], rewrite: dict[str, Any]) -> str:
    """The Pinecone query_string of a rewritten text query: one clause per field, joined by OR, a boosted field
    as (field:(...))^w; phrase "..."~slop, phrase prefix "..."*, terms with a fuzzy suffix, a required + per term, a regular
    expression /pattern/, or the query_string text itself. The words and, or and not are quoted, not read as operators."""
    kind = rewrite["type"]
    if kind == "regexp":
        if "/" in query:
            raise ValueError(f"the regular expression {query!r} contains '/', which Pinecone query_string cannot escape")
        body = "/" + query + "/"
    elif kind == "query_string":
        body = "(" + query + ")"
    else:
        terms = _terms(query)
        if not terms:
            raise ValueError(f"the query {query!r} has no terms")
        if kind in ("phrase", "phrase_prefix"):
            if kind == "phrase_prefix" and len(terms) < 2:
                raise ValueError(f"a phrase prefix needs at least two terms on Pinecone: {query!r}")
            suffix = "*" if kind == "phrase_prefix" else ""
            if "slop" in rewrite:
                suffix += "~" + str(int(rewrite["slop"]))
            body = '("' + " ".join(terms) + '"' + suffix + ")"
        else:
            sign = "+" if rewrite.get("required") else ""
            fuzzy = rewrite.get("fuzzy", "")
            body = "(" + " ".join(sign + ('"' + term + '"' if term in _OPERATORS else term + fuzzy) for term in terms) + ")"
    boosts = rewrite.get("boosts") or {}
    return " OR ".join(f"({field}:{body})^{boosts[field]}" if field in boosts else f"{field}:{body}" for field in fields)


def _text_clause(query: str, fields: Sequence[str], query_string: bool = False,
                 rewrite: dict[str, Any] | None = None) -> dict[str, Any]:
    if rewrite is not None:
        return {"type": "query_string", "query": query_string_text(query, fields, rewrite)}
    if query_string:
        return {"type": "query_string", "query": query}
    return {"type": "text", "fields": list(fields), "query": query}


def keyword_search(client: Client, collection: dict[str, Any], query: str, fields: Sequence[str], limit: int,
                   output: Sequence[str], query_string: bool = False, filter: dict[str, Any] | None = None,
                   offset: int | None = None, score_min: float | None = None, score_max: float | None = None,
                   vectors: Sequence[str] | None = None, rewrite: dict[str, Any] | None = None,
                   rerank: dict[str, Any] | None = None) -> list[dict[str, Any]]:
    matches = _search(client, collection, _text_clause(query, fields, query_string, rewrite), limit + (offset or 0),
                      _ranked(_included(collection, output, vectors), rerank), filter)
    scored = [(match, _hit(collection, match, float(match.score), output, vectors)) for match in matches
              if _within(float(match.score), score_min, score_max)]
    return _page(_rerank(client, rerank, scored), limit, offset)


def _leg_scores(client: Client, collection: dict[str, Any], leg: dict[str, Any], top_k: int,
                fields: Sequence[str]) -> list[tuple[Any, float]]:
    if leg["kind"] == "vector":
        clause = _vector_clause(leg["field"], leg["vector"], leg.get("embed"))
        scored = [(match, _similarity(leg["metric"], float(match.score)))
                  for match in _search(client, collection, clause, top_k, fields, leg.get("filter"))]
        return [(match, score) for match, score in scored if _within(score, leg.get("score_min"), leg.get("score_max"))]
    clause = _text_clause(leg["query"], leg["fields"], bool(leg.get("query_string")), leg.get("rewrite"))
    return [(match, float(match.score)) for match in _search(client, collection, clause, top_k, fields, leg.get("filter"))]


def _fused(fusion: str, k: int, weight: float, ranked: list[tuple[Any, float]]) -> dict[str, float]:
    """Contribution of one leg: 1/(k + rank), weight * similarity, or weight * min-max normalized score."""
    if fusion == "rrf":
        return {match.id: 1.0 / (k + rank) for rank, (match, _) in enumerate(ranked, start=1)}
    if fusion == "weighted":
        return {match.id: weight * score for match, score in ranked}
    low = min((score for _, score in ranked), default=0.0)
    high = max((score for _, score in ranked), default=0.0)
    return {match.id: weight * ((score - low) / (high - low) if high > low else 1.0) for match, score in ranked}


def hybrid_search(client: Client, collection: dict[str, Any], legs: Sequence[dict[str, Any]], limit: int, fusion: str,
                  output: Sequence[str], k: int = 60, offset: int | None = None, score_min: float | None = None,
                  score_max: float | None = None, vectors: Sequence[str] | None = None,
                  rerank: dict[str, Any] | None = None) -> list[dict[str, Any]]:
    """Fuses the legs' searches in the runtime; a Pinecone search scores by one vector clause or text clauses."""
    fields = _ranked(_included(collection, output, vectors), rerank)
    totals: dict[str, float] = {}
    documents: dict[str, Any] = {}
    for leg in legs:
        ranked = _leg_scores(client, collection, leg, int(leg.get("limit", limit + (offset or 0))), fields)
        for match, _ in ranked:
            documents.setdefault(match.id, match)
        for doc_id, part in _fused(fusion, k, float(leg.get("weight", 1.0)), ranked).items():
            totals[doc_id] = totals.get(doc_id, 0.0) + part
    order = _order(collection)
    ranking = sorted(totals, key=lambda doc_id: (-totals[doc_id], order(doc_id)))
    scored = [(documents[doc_id], _hit(collection, documents[doc_id], totals[doc_id], output, vectors)) for doc_id in ranking
              if _within(totals[doc_id], score_min, score_max)]
    return _page(_rerank(client, rerank, scored), limit, offset)


def lookup_vector(client: Client, collection: dict[str, Any], field: str, id: Any) -> Any:
    found = _fetch(client, collection, [document_id(id)], [field])
    if document_id(id) not in found:
        raise KeyError(f"record {id!r} not found in {collection['name']}")
    return _vector(found[document_id(id)].get(field))


def embed_query(client: Client, model: str, text: str, parameters: dict[str, Any]) -> Any:
    """A query text embedded by Pinecone Inference embed: dense values, or the indices and values of a sparse model."""
    data = _control(client, "POST", "/embed", {"model": model, "parameters": parameters, "inputs": [{"text": text}]})["data"][0]
    if data.get("vector_type") == "sparse":
        return {"indices": [int(i) for i in data["sparse_indices"]], "values": [float(x) for x in data["sparse_values"]]}
    return [float(x) for x in data["values"]]


def recommend_vector(client: Client, collection: dict[str, Any], field: str, positives: Sequence[Any],
                     negatives: Sequence[Any] = ()) -> list[float]:
    """Centroid of the positive examples, moved away from the centroid of the negatives: 2p - n."""
    keys = [document_id(item) for item in [*positives, *negatives] if not isinstance(item, (list, tuple, dict))]
    stored = {doc_id: _vector(document.get(field))
              for doc_id, document in _fetch(client, collection, keys, [field]).items()} if keys else {}

    def resolve(items: Sequence[Any]) -> list[Any]:
        resolved = []
        for item in items:
            if isinstance(item, (list, tuple, dict)):
                resolved.append(_vector(item))
            elif document_id(item) in stored:
                resolved.append(stored[document_id(item)])
            else:
                raise KeyError(f"record {item!r} not found in {collection['name']}")
        return resolved

    positive = resolve(positives)
    negative = resolve(negatives)
    if not positive:
        raise ValueError("recommend requires at least one positive example")
    if isinstance(positive[0], dict):
        return _sparse_centroid(positive, negative)
    centroid = [sum(values) / len(positive) for values in zip(*positive)]
    if negative:
        anti = [sum(values) / len(negative) for values in zip(*negative)]
        centroid = [2 * c - a for c, a in zip(centroid, anti)]
    return centroid


def _sparse_mean(vectors: Sequence[dict[str, Any]]) -> dict[int, float]:
    total: dict[int, float] = {}
    for vector in vectors:
        for index, weight in zip(vector["indices"], vector["values"]):
            total[index] = total.get(index, 0.0) + weight
    return {index: weight / len(vectors) for index, weight in total.items()}


def _sparse_centroid(positive: Sequence[dict[str, Any]], negative: Sequence[dict[str, Any]]) -> dict[str, Any]:
    """The sparse form of 2p - n, in ascending index order without zero weights."""
    centroid = _sparse_mean(positive)
    if negative:
        anti = _sparse_mean(negative)
        centroid = {index: 2 * centroid.get(index, 0.0) - anti.get(index, 0.0) for index in {*centroid, *anti}}
    indices = sorted(index for index, weight in centroid.items() if weight != 0)
    return {"indices": indices, "values": [centroid[index] for index in indices]}


def sample_rows(client: Client, collection: dict[str, Any], size: int, output: Sequence[str], first: bool = False,
                filter: dict[str, Any] | None = None) -> list[dict[str, Any]]:
    """A random sample (or the first records in key order) of the matching records, returned in key order."""
    doc_ids = sorted(_all_ids(client, collection) if filter is None else _matching(client, collection, filter),
                     key=_order(collection))
    picked = doc_ids[:int(size)] if first else sorted(random.sample(doc_ids, min(int(size), len(doc_ids))), key=_order(collection))
    found = _fetch(client, collection, picked, _included(collection, output, None))
    return [_row(collection, doc_id, found[doc_id], output, None) for doc_id in picked if doc_id in found]


def distance_matrix(client: Client, collection: dict[str, Any], field: str, metric: str, sample: int = 10, limit: int = 3,
                    filter: dict[str, Any] | None = None) -> list[dict[str, Any]]:
    """A random sample of the matching records, each paired with its nearest neighbours within the sample (as Qdrant's
    distance matrix), with primary keys and canonical similarities, sorted by key; a record without the vector has no pairs."""
    doc_ids = _all_ids(client, collection) if filter is None else _matching(client, collection, filter)
    picked = random.sample(doc_ids, min(int(sample), len(doc_ids)))
    stored = _fetch(client, collection, picked, [field])
    keys = [_key(collection, doc_id) for doc_id in picked]
    pairs = []
    for doc_id in picked:
        if stored.get(doc_id, {}).get(field) is None:
            continue
        clause = _vector_clause(field, stored[doc_id].get(field))
        matches = _search(client, collection, clause, min(int(limit) + 1, len(picked)), [collection["key"]],
                          {collection["key"]: {"$in": keys}})
        neighbours = [match for match in matches if match.id != doc_id][:int(limit)]
        for match in neighbours:
            pairs.append({"a": _key(collection, doc_id), "b": _key(collection, match.id),
                          "score": _value(_similarity(metric, float(match.score)))})
    return sorted(pairs, key=lambda pair: (pair["a"], pair["b"]))


# ---------------------------------------------------------------- operations

def describe(client: Client, name: str, stats: bool = False, index_progress: bool = False) -> dict[str, Any]:
    """Name, schema field types, the dense field's dimension and metric, deletion protection and tags; stats adds the
    record counts of describe_index_stats (eventually consistent), index-progress the index state."""
    found = _describe(client, name)
    fields = (found.get("schema") or {}).get("fields") or {}
    result: dict[str, Any] = {"name": found["name"], "fields": {key: fields[key].get("type") for key in sorted(fields)},
                              "deletion_protection": found.get("deletion_protection"),
                              "tags": sorted(found.get("tags") or {})}
    for config in fields.values():
        if config.get("type") == "dense_vector":
            result["dimension"] = config.get("dimension")
            result["metric"] = config.get("metric")
    if stats:
        namespaces = (_data(client, name, "POST", "/describe_index_stats", {}) or {}).get("namespaces") or {}
        counts = {key: int((namespaces[key] or {}).get("vectorCount") or 0) for key in sorted(namespaces)}
        result["count"] = sum(counts.values())
        result["namespaces"] = counts
    if index_progress:
        status = found.get("status") or {}
        result["index_progress"] = "ready" if status.get("ready") else str(status.get("state", "")).lower()
    return result


def await_index(client: Client, name: str, timeout: float | None = None) -> str:
    """Waits until the index reports ready; Pinecone indexes every write itself, so readiness is the build state."""
    _poll(lambda: _ready(client, name), f"index {name} is not ready", _index_timeout_seconds() if timeout is None else timeout)
    return "ready" if _ready(client, name) else str((_describe(client, name).get("status") or {}).get("state", "")).lower()


def _names(items: Sequence[Any], prefix: str | None, limit: int | None) -> list[str]:
    names = sorted({item for item in items if prefix is None or item.startswith(prefix)})
    return names if limit is None else names[:int(limit)]


def _backups(client: Client, name: str | None = None) -> list[dict[str, Any]]:
    path = "/backups" if name is None else f"/indexes/{_segment(name)}/backups"
    return _paged(lambda token: _control(client, "GET", path + _query(paginationToken=token)), "data")


def list_objects(client: Client, kind: str, scope: dict[str, Any] | None = None, prefix: str | None = None,
                 limit: int | None = None) -> list[str]:
    """Sorted names: the project's indexes, an index's namespaces, or the backups of an index or the project."""
    if kind == "collections":
        items = [index["name"] for index in (_control(client, "GET", "/indexes") or {}).get("indexes") or []]
    elif kind == "namespaces":
        assert scope is not None
        items = [item["name"] for item in _paged(lambda token: _data(
            client, scope["name"], "GET", "/namespaces" + _query(limit=100, paginationToken=token)), "namespaces")]
    else:
        items = [backup["name"] for backup in _backups(client, None if scope is None else scope["name"]) if backup.get("name")]
    return _names(items, prefix, limit)


def create_backup(client: Client, name: str, backup: str, description: str | None = None) -> dict[str, Any]:
    """A backup of every namespace of the index (paid plans); waits until it is ready."""
    body: dict[str, Any] = {"name": backup}
    if description is not None:
        body["description"] = description
    created = _control(client, "POST", f"/indexes/{_segment(name)}/backups", body)
    backup_id = created["backup_id"]

    def status() -> str:
        return str(_control(client, "GET", "/backups/" + _segment(backup_id)).get("status"))

    _poll(lambda: status() in ("Ready", "InitializationFailed"), f"backup {backup} is not ready", _index_timeout_seconds())
    final = status()
    if final == "InitializationFailed":
        raise RuntimeError(f"backup {backup} of {name} failed")
    return {"backup": backup, "status": final}


def _backup(client: Client, backup: str) -> dict[str, Any]:
    found = [item for item in _backups(client) if item.get("name") == backup and item.get("status") == "Ready"]
    if not found:
        raise KeyError(f"no ready backup named {backup}")
    return max(found, key=lambda item: str(item.get("created_at") or ""))


def restore_backup(client: Client, name: str, backup: str, background: bool = False) -> dict[str, Any]:
    """Replaces the index with one created from the newest ready backup of that name (paid plans)."""
    source = _backup(client, backup)
    if has_collection(client, name):
        drop_collection(client, name)
    job = _control(client, "POST", f"/backups/{_segment(source['backup_id'])}/create-index", {"name": name})["restore_job_id"]

    def status() -> str:
        return str(_control(client, "GET", "/restore-jobs/" + _segment(job)).get("status"))

    if not background:
        _poll(lambda: status() in ("Completed", "Failed", "Cancelled"), f"restore of {name} has not finished", _index_timeout_seconds())
        _poll(lambda: _ready(client, name), f"index {name} is not ready", _index_timeout_seconds())
    final = status()
    if final in ("Failed", "Cancelled"):
        raise RuntimeError(f"restore of {name} from {backup} ended {final}")
    return {"restored": name, "status": final}


def drop_backup(client: Client, backup: str) -> dict[str, int]:
    found = [item for item in _backups(client) if item.get("name") == backup]
    if not found:
        raise KeyError(f"no backup named {backup}")
    for item in found:
        _control(client, "DELETE", "/backups/" + _segment(item["backup_id"]))
    return {"deleted": len(found)}


_SCHEMA_KEYS = {"dense_vector": ("type", "dimension", "metric", "description"), "sparse_vector": ("type", "description"),
                "string": ("type", "description", "full_text_search", "embed", "sparse_embed", "store_text")}
_TEXT_KEYS = ("language", "stemming", "stop_words", "ngram")


def _create_schema(fields: dict[str, Any]) -> dict[str, Any]:
    """The schema of a described index in the form create accepts: server-set keys (lowercase, max_term_len) removed."""
    result: dict[str, Any] = {}
    for name in sorted(fields):
        config = fields[name] or {}
        keys = _SCHEMA_KEYS.get(config.get("type"))
        if keys is None:
            continue
        entry = {key: config[key] for key in keys if config.get(key) is not None}
        if "full_text_search" in entry:
            entry["full_text_search"] = {key: value for key, value in entry["full_text_search"].items()
                                         if key in _TEXT_KEYS and value is not None}
        result[name] = entry
    return result


def _list_ids(client: Client, name: str, namespace: str) -> list[str]:
    path = f"/namespaces/{_segment(namespace)}/documents/list"
    return [item["_id"] for item in _paged(lambda token: _data(
        client, name, "POST", path, {"limit": _LIST_PAGE, **({} if token is None else {"pagination_token": token})}),
        "documents")]


def _create_rest(client: Client, name: str, fields: dict[str, Any], deployment: dict[str, Any],
                 tags: dict[str, str] | None) -> None:
    """create_index over REST with the schema as described, then the wait until the index is ready."""
    body: dict[str, Any] = {"name": name, "schema": {"fields": fields},
                            "deployment": {"deployment_type": "managed",
                                           "cloud": os.environ.get("VECDSL_PINECONE_CLOUD", DEFAULT_CLOUD),
                                           "region": os.environ.get("VECDSL_PINECONE_REGION", DEFAULT_REGION),
                                           **deployment}}
    if tags:
        body["tags"] = tags
    _control(client, "POST", "/indexes", body)
    _poll(lambda: _ready(client, name), f"index {name} is not ready", _index_timeout_seconds())


def clone_collection(client: Client, collection: dict[str, Any], target: str,
                     deployment: dict[str, Any] | None = None) -> dict[str, int]:
    """A new index with the source's schema, deployment and tags, filled with a copy of every namespace."""
    source = _describe(client, collection["name"])
    placed = {key: value for key, value in (source.get("deployment") or {}).items() if key in ("cloud", "region")}
    _create_rest(client, target, _create_schema((source.get("schema") or {}).get("fields") or {}),
                 {**placed, **(deployment or {})}, source.get("tags") or None)
    namespaces = sorted({DEFAULT_NAMESPACE, *list_objects(client, "namespaces", {"name": collection["name"]})})
    fields = (source.get("schema") or {}).get("fields") or {}
    batch = _EMBEDDED_BATCH if any("embed" in (config or {}) or "sparse_embed" in (config or {}) for config in fields.values()) \
        else _BATCH
    copied = 0
    positions: dict[str, int | None] = {}
    copies: dict[str, list[dict[str, Any]]] = {}
    for namespace in namespaces:
        for chunk in _chunks(_list_ids(client, collection["name"], namespace), batch):
            path = f"/namespaces/{_segment(namespace)}/documents/"
            documents = (_data(client, collection["name"], "POST", path + "fetch", {"ids": list(chunk)}) or {}).get("documents") or {}
            copy = [{key: value for key, value in documents[doc_id].items() if key != "_score"} for doc_id in chunk if doc_id in documents]
            if copy:
                _data(client, target, "POST", path + "upsert", {"documents": copy})
                positions[namespace] = client.committed
                copies.setdefault(namespace, []).extend(copy)
                copied += len(copy)
    probe = _probe(_create_schema((source.get("schema") or {}).get("fields") or {}))
    for namespace, position in positions.items():
        _await_rest(client, target, namespace, probe, position)
        copy_layout = {"name": target, "namespace": namespace, "key": collection["key"], "key_type": collection["key_type"]}
        _settle(client, copy_layout, copies[namespace], (), time.monotonic() + _seconds("VECDSL_PINECONE_WAIT_SECONDS", 60))
    return {"copied": copied}


def _probe(fields: dict[str, Any]) -> dict[str, Any] | None:
    """A search clause that observes the log position of an index: its dense field, else a full-text field."""
    for name, config in fields.items():
        if config.get("type") == "dense_vector":
            return {"type": "dense_vector", "field": name, "values": [1.0] + [0.0] * (int(config["dimension"]) - 1)}
    for name, config in fields.items():
        if config.get("type") == "string" and "full_text_search" in config:
            return {"type": "text", "field": name, "query": "vecdsl"}
    return None


def _await_rest(client: Client, name: str, namespace: str, probe: dict[str, Any] | None, target: int | None) -> None:
    """The REST form of _await: searches until the reconciled log position reaches the write's."""
    if probe is None or target is None:
        return
    deadline = time.monotonic() + _seconds("VECDSL_PINECONE_WAIT_SECONDS", 60)
    path = f"/namespaces/{_segment(namespace)}/documents/search"
    while True:
        _data(client, name, "POST", path, {"score_by": [probe], "top_k": 1})
        if client.reconciled is not None and client.reconciled >= target:
            return
        if time.monotonic() > deadline:
            raise TimeoutError(f"{name} did not reach log position {target}")
        time.sleep(0.5)
